INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7, 106001, 1, 7001, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7, 105901, 1, 7002, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7, 105801, 1, 7003, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10, 105801, 1, 10001, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10, 106001, 1, 10002, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10, 105901, 1, 10003, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10, 106401, 1, 10004, "シェフィ", 0, -363.0, 0.0, 0.0, 2, 1, 2104010, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (12, 105801, 1, 12001, "ペコリーヌ", 0, -416.5, 0.0, 0.0, 1, 1, 0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13, 106001, 1, 13001, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13, 105901, 1, 13002, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13, 106401, 1, 13003, "シェフィ", 0, -363.0, 0.0, 0.0, 2, 1, 2104010, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13, 105801, 1, 13004, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14, 105901, 1, 14001, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14, 106401, 1, 14002, "シェフィ", 0, -363.0, 0.0, 0.0, 2, 1, 2104010, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14, 105801, 1, 14003, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14, 106001, 1, 14004, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (15, 105901, 1, 15001, "コッコロ", 0, -470.0, 0.0, 0.0, 1, 1, 0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16, 106401, 1, 16001, "シェフィ", 0, -363.0, 0.0, 0.0, 2, 1, 2104010, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16, 105801, 1, 16002, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16, 106001, 1, 16003, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16, 105901, 1, 16004, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (17, 105901, 1, 17002, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (25, 106001, 1, 17004, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (25, 105901, 1, 17005, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (25, 106401, 1, 17006, "シェフィ", 0, -363.0, 0.0, 0.0, 2, 1, 2104010, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (25, 105801, 1, 17007, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (18, 190801, 1, 18001, "カリン", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (18, 190801, 2, 18002, "カリン", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (19, 190801, 3, 19001, "カリン", 0, -470.0, 0.0, 0.0, 1, 1, 0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (19, 190801, 4, 19002, "カリン", 0, -470.0, 0.0, 0.0, 1, 1, 0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (20, 190801, 5, 20001, "カリン", 0, -470.0, 0.0, 0.0, 1, 1, 0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (20, 190801, 6, 20002, "カリン", 0, -470.0, 0.0, 0.0, 1, 1, 0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21, 106001, 1, 21001, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21, 105901, 1, 21002, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21, 106401, 1, 21003, "シェフィ", 0, -363.0, 0.0, 0.0, 2, 1, 2104010, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21, 105801, 1, 21004, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (22, 190801, 1, 22001, "カリン", 0, -430.0, 0.0, 0.0, 1, 1, 0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (22, 190801, 2, 22002, "カリン", 0, -430.0, 0.0, 0.0, 1, 1, 0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (23, 190801, 3, 23001, "カリン", 0, -430.0, 0.0, 0.0, 1, 1, 0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (23, 190801, 4, 23002, "カリン", 0, -430.0, 0.0, 0.0, 1, 1, 0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109001, 1, 24001, "エリコ（バレンタイン）", 10011, -385.0, 8.0, 4.08, 1, 2, 0, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109001, 2, 24002, "エリコ（バレンタイン）", 10011, -385.0, 8.0, 5.0, 1, 2, 0, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109001, 3, 24003, "エリコ（バレンタイン）", 10011, -385.0, 8.0, 10.11, 1, 2, 0, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109001, 4, 24004, "エリコ（バレンタイン）", 10011, -385.0, 8.0, 4.0, 1, 2, 0, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109001, 5, 24005, "エリコ（バレンタイン）", 10011, -385.0, 8.0, 6.0, 1, 2, 0, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109002, 6, 24006, "エリコ（バレンタイン）", 10011, 0.0, 0.0, 0.0, 1, 1, 0, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109002, 7, 24007, "エリコ（バレンタイン）", 10011, 0.0, 0.0, 0.0, 1, 1, 0, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109002, 8, 24008, "エリコ（バレンタイン）", 10011, 0.0, 0.0, 0.0, 1, 1, 0, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109002, 9, 24009, "エリコ（バレンタイン）", 10011, 0.0, 0.0, 0.0, 1, 1, 0, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109002, 10, 24010, "エリコ（バレンタイン）", 10011, 0.0, 0.0, 0.0, 1, 1, 0, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109101, 1, 24011, "シズル（バレンタイン）", 10011, -385.0, 8.0, 2.12, 1, 2, 0, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109101, 2, 24012, "シズル（バレンタイン）", 10011, -385.0, 8.0, 4.19, 5, 2, 0, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109101, 3, 24013, "シズル（バレンタイン）", 10011, -385.0, 8.0, 2.3, 2, 4, 0, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109102, 4, 24014, "シズル（バレンタイン）", 10011, 0.0, 0.0, 0.0, 1, 1, 0, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109101, 5, 24015, "シズル（バレンタイン）", 10011, -385.0, 8.0, 5.23, 5, 2, 0, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109102, 6, 24016, "シズル（バレンタイン）", 10011, 0.0, 0.0, 0.0, 1, 1, 0, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109101, 7, 24017, "シズル（バレンタイン）", 10011, -385.0, 8.0, 5.01, 1, 2, 0, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109102, 8, 24018, "シズル（バレンタイン）", 10011, 0.0, 0.0, 0.0, 1, 1, 0, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109102, 9, 24019, "シズル（バレンタイン）", 10011, 0.0, 0.0, 0.0, 1, 1, 0, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 109102, 10, 24020, "シズル（バレンタイン）", 10011, 0.0, 0.0, 0.0, 1, 1, 0, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", "2019/01/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26, 106401, 1, 26001, "シェフィ", 0, -363.0, 0.0, 0.0, 2, 1, 2104010, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26, 105801, 1, 26002, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26, 106001, 1, 26003, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26, 105901, 1, 26004, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27, 106401, 1, 27001, "シェフィ", 0, -363.0, 0.0, 0.0, 2, 1, 2104010, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27, 105801, 1, 27002, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27, 106001, 1, 27003, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27, 105901, 1, 27004, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (28, 190801, 1, 28001, "カリン", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", "2019/09/24 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (28, 190801, 2, 28002, "カリン", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", "2019/09/24 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (29, 190801, 3, 29001, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", "2019/09/24 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (29, 190801, 4, 29002, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", "2019/09/24 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (30, 190801, 5, 30001, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", "2019/09/24 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (30, 190801, 6, 30002, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", "2019/09/24 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (31, 190801, 7, 31001, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", "2019/10/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (31, 190801, 8, 31002, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", "2019/10/31 12:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (32, 190801, 1, 32001, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", "2019/12/20 5:00:00", "2020/01/04 4:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (32, 190801, 2, 32002, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "2019/12/20 5:00:00", "2020/01/04 4:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (33, 190801, 3, 33001, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", "2019/12/20 5:00:00", "2020/01/04 4:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (33, 190801, 4, 33002, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "2019/12/20 5:00:00", "2020/01/04 4:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (34, 190801, 5, 34001, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", "2020/01/04 5:00:00", "2020/01/10 11:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (34, 190801, 6, 34002, "カリン", 0, -409.0, 0.0, 0.0, 1, 1, 0, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", "2020/01/04 5:00:00", "2020/01/10 11:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (38, 105801, 1, 38001, "ペコリーヌ", 0, -458.0, 0.0, 5.3, 1, 2, 0, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (38, 105801, 2, 38002, "ペコリーヌ", 0, -458.0, 0.0, 6.5, 1, 2, 0, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (39, 105801, 0, 39005, "ペコリーヌ", 0, 9999.0, 9999.0, 0.0, 3, 3, 0, "", "2020/04/01", "2020/04/08 23:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (40, 190801, 2, 40001, "カリン", 0, -430.0, 0.0, 0.0, 1, 1, 0, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41, 106401, 1, 41001, "シェフィ", 0, -363.0, 0.0, 0.0, 1, 1, 2104010, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41, 105801, 1, 41002, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41, 106001, 1, 41003, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41, 105901, 1, 41004, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42, 105901, 1, 42001, "コッコロ", 0, -416.5, 0.0, 0.0, 1, 1, 0, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42, 106401, 1, 42002, "シェフィ", 0, -416.5, 0.0, 0.0, 1, 1, 2104010, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42, 105801, 1, 42003, "ペコリーヌ", 0, -416.5, 0.0, 0.0, 1, 1, 0, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42, 106001, 1, 42004, "キャル", 0, -416.5, 0.0, 0.0, 1, 1, 0, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43, 105801, 1, 43001, "ペコリーヌ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43, 105901, 1, 43002, "コッコロ", 0, -363.0, 0.0, 0.0, 1, 1, 0, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43, 106001, 1, 43003, "キャル", 0, -363.0, 0.0, 0.0, 1, 1, 0, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (44, 123001, 1, 43004, "アメス", 0, -416.5, 0.0, 0.0, 1, 1, 0, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (44, 123001, 2, 43005, "アメス", 0, -416.5, 0.0, 0.0, 1, 1, 0, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (45, 123001, 3, 43006, "アメス", 0, -416.5, 0.0, 5.79, 1, 2, 0, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (46, 123001, 1, 46001, "アメス", 0, -371.5, 0.0, 0.0, 1, 1, 0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (47, 104901, 1, 47001, "シズル", 0, -416.5, 0.0, 0.0, 2, 2, 0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (47, 101101, 1, 47002, "リノ", 0, -416.5, 0.0, 9.32, 1, 2, 0, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (48, 104901, 0, 48001, "シズル", 0, -470.0, 0.0, 0.0, 2, 2, 0, "", "2015/12/17 15:00:00", "2030/12/17 14:59:59");
